const TITLES=Object.keys(D);

/* ---------- actions ---------- */
function render(){const v=S.view;if(!D[v])return;const el=$('#v-dyn');el.innerHTML=D[v]();bindDyn()}
function bindDyn(){const li=$('#logo-in');if(li)li.onchange=e=>{const f=e.target.files[0];if(!f)return;S.logo=URL.createObjectURL(f);$$('img.seal,#club-logo').forEach(i=>i.src=S.logo);toast('Logo updated for this demo session. Real logo changes go through Student Life.')};const cf=$('#chatform');if(cf)cf.onsubmit=e=>{e.preventDefault();const v=$('#chatin').value.trim();if(v)ask(v)};
 const ms=$('#msearch');if(ms)ms.oninput=()=>{S.f.q=ms.value;const q=ms.value.toLowerCase();$('#mlist').innerHTML=S.members.filter(m=>m.n.toLowerCase().includes(q)).map(m=>lrow({av:m.av,t:m.n,s:m.r,act:'data-act="member" data-v="'+esc(m.n)+'"'})).join('')||'<div class="pad cap">No members match.</div>'};
 const inv=$('#inviteform');if(inv)inv.onsubmit=e=>{e.preventDefault();const n=$('#iname').value.trim(),m=$('#imail').value.trim();const okm=/cuny\.edu$/i.test(m);$('#f-iname').classList.toggle('bad',!n);$('#f-imail').classList.toggle('bad',!okm);if(!n||!okm)return;S.invites.unshift({n,e:m,r:$('#irole').value});audit('Aisha Rahman','Access','INVITE_SENT · '+n);toast('Invitation sent (simulated)');render()}}
function ask(q){S.chat.push({me:true,t:q});S.typing=true;render();setTimeout(()=>{S.typing=false;const l=q.toLowerCase();let a;
 if(l.includes('wcag')||l.includes('access'))a='For flyers and posts:\n• Write alt text that says what the image shows and why it matters.\n• Keep text contrast at 4.5:1 or more (CUNY Blue on white passes).\n• Use CamelCase hashtags (#CunySps) so screen readers can say them.\n• Don’t put key details only inside the image; repeat date, time and place in the caption.';
 else if(l.includes('2-week')||l.includes('sequence')||l.includes('plan'))a='A 2-week plan for Build Night:\n• Day 1: announcement with photo and RSVP link\n• Day 5: speaker or project teaser\n• Day 10: "seats filling up" reminder\n• Day 13: logistics (room, Zoom link)\n• Day 14 morning: final reminder\n• Day 15: recap with photos';
 else if(l.includes('angle')||l.includes('introduce'))a='Three angles:\n1. "Built by working adults": show members fitting AI projects around jobs.\n2. "No CS degree needed": highlight members from non-technical programs.\n3. "Learn it, then shape it": tie events to AI ethics and civic tech.';
 else a='Here’s a draft you can edit:\n“Join the CUNY SPS AI Club this week. Whether you’re new to AI or already building, there’s a seat for you. RSVP in the Club Social Hub.”';
 S.chat.push({me:false,t:a,use:true});if(S.view==='assistant'){render();const cl=$('#chatlog');cl&&cl.lastElementChild&&cl.lastElementChild.scrollIntoView({block:'nearest'})}},380)}
const ACT={
 reqAcct(){openSheet('<h2 class="h2 mb8">Request a new official account</h2><p class="cap mb12">Goes to Student Life, then CUNY Communications. Accounts are owned by CUNY SPS, never by a student.</p><div class="field"><label class="label" for="rq-p">Platform</label><select id="rq-p"><option>LinkedIn</option><option>TikTok</option><option>YouTube</option><option>Threads</option></select></div><div class="field"><label class="label" for="rq-r">Purpose</label><textarea id="rq-r">Share club events and student projects with alumni and employers.</textarea></div><button class="btn pri block" id="rq-go">Submit request</button>');
  $('#rq-go').onclick=()=>{const p=$('#rq-p').value,id='REQ-2026-0'+(15+S.reqs.length);S.reqs.unshift({id,t:'New Official Account: AI Club '+p,p,club:'Artificial Intelligence Club',step:0,st:'Submitted',by:'Aisha Rahman · Nov 18'});audit('Aisha Rahman','Governance','ACCOUNT_REQUEST_SUBMITTED · '+id);closeAll();toast(id+' submitted to Student Life');go('requests')}},
 connect(){openSheet('<h2 class="h2 mb8">Connect an approved account</h2><p class="cap mb12">Only accounts already approved by Student Life and CUNY Communications can be connected.</p><div class="field"><label class="label" for="cx">Approved account</label><select id="cx"><option>Instagram Professional · @cunyspsai</option></select></div><ol class="steps2 mb12"><li class="cur">Continue to Facebook Login for Business (opens Meta)</li><li>Confirm the Page and linked Instagram account</li><li>Meta shows the permissions the Hub needs</li><li>The connection is recorded for this club</li></ol><div class="note mb12">SPS staff stay the account custodian. The Hub never asks for the account password.</div><button class="btn pri block" id="cx-go">Continue to Facebook (simulated)</button>');$('#cx-go').onclick=()=>{closeAll();toast('In the real app, Meta’s login opens here')}},
 health(v){toast((S.accts.find(a=>a.id===v)||{}).n+': token valid, permissions OK (simulated)')},
 disc(v){const a=S.accts.find(x=>x.id===v);openSheet('<h2 class="h2 mb8">Disconnect '+a.n+'?</h2><p class="cap mb16">The Hub stops posting to '+a.h+'. CUNY SPS still owns the account, and scheduled posts to it will pause.</p><div class="two"><button class="btn sec" id="dc-no">Cancel</button><button class="btn pri" id="dc-yes">Disconnect</button></div>');$('#dc-no').onclick=closeAll;$('#dc-yes').onclick=()=>{a.on=false;audit('Aisha Rahman','Access','ACCOUNT_DISCONNECTED · '+a.h);closeAll();toast(a.n+' disconnected');render()}},
 reconn(v){const a=S.accts.find(x=>x.id===v);a.on=true;toast(a.n+' reconnected (simulated)');render()},
 ask(v){ask(v)},useAI(){const last=[...S.chat].reverse().find(m=>!m.me&&m.use);resetPost();$('#copy').value=last.t.replace(/^Here[’']s a draft you can edit:\n[“"]|[”"]$/g,'');$('#copy').oninput();setPhoto(PHOTOS[0]);go('create');toast('Draft added to a new post. Review before posting.')},
 dictate(){toast('Dictation uses the microphone, which this demo can’t access')},
 openMsg(v){S.f.msg=+v;S.f.draft='';S.unreadInbox=0;go('message')},
 aiReply(){const x=S.inbox.find(i=>i.id===S.f.msg);S.f.draft=x.tag==='Join inquiry'?'Hi '+x.who.split(' ')[0]+'! Yes, the AI Club is open to every CUNY SPS program. Tap "Request to join" in the Club Social Hub and we’ll add you.':'Hi '+x.who.split(' ')[0]+', yes! The recording and slides will be in Club Resources within 48 hours of the event.';render();toast('AI draft added. Edit before you send.')},
 sendReply(){const t=$('#reply').value.trim();if(!t){toast('Write a reply first');return}const x=S.inbox.find(i=>i.id===S.f.msg);x.thread.push(t);S.f.draft='';audit('Aisha Rahman','Publishing','INBOX_REPLY · '+x.pl+' · '+x.who);toast('Reply sent (simulated)');render()},
 escalate(){const x=S.inbox.find(i=>i.id===S.f.msg);x.esc=true;audit('Aisha Rahman','Governance','INBOX_ESCALATED · '+x.who);toast('Escalated to Student Life staff');go('inbox')},
 readAll(){S.notes.forEach(n=>n.u=false);S.unread=0;render()},
 openNote(v){const n=S.notes.find(x=>x.id==v);if(n.u){n.u=false;S.unread--}go(n.go)},
 ack(v){S.ann.find(a=>a.id==v).ack=true;toast('Marked as read. Student Life can see who has read critical notices.');render()},
 ics(){try{navigator.clipboard.writeText('https://hub.example.edu/ics/ai-club.ics').then(()=>toast('Calendar feed link copied (sample link)'),()=>toast('Calendar feed: hub.example.edu/ics/ai-club.ics (sample)'))}catch(e){toast('Calendar feed: hub.example.edu/ics/ai-club.ics (sample)')}},
 logAtt(){openSheet('<h2 class="h2 mb8">Log attendance</h2><div class="field"><label class="label" for="la-ev">Event</label><select id="la-ev">'+EVENTS.slice(0,3).map(e=>'<option value="'+e.id+'">'+e.title+'</option>').join('')+'</select></div><div class="field"><label class="label" for="la-n">Verified check-ins</label><input id="la-n" type="number" min="0" value="30"></div><button class="btn pri block" id="la-go">Save</button>');$('#la-go').onclick=()=>{S.attLog[$('#la-ev').value]=+$('#la-n').value||0;closeAll();toast('Attendance logged');render()}},
 csv(){toast('Exports download in the real app. This demo can’t save files.')},
 remToggle(){S.rem.on=!S.rem.on;render()},
 sweep(){if(!S.rem.on){toast('Turn on auto-reminders first');return}const q=S.rem.queue.filter(x=>x.st==='Queued');q.forEach(x=>x.st='Sent');audit('System','Publishing','REMINDER_SWEEP · '+q.length+' events');toast(q.length?q.reduce((n,x)=>n+x.n,0)+' reminder emails sent (simulated)':'Nothing due in the next 24 hours');render()},
 telemetry(){openSheet('<h2 class="h2 mb12">Delivery log</h2><div class="card">'+lrow({t:'MSA Community Tea & Study Circle',s:'2 delivered · 0 bounced · Nov 17',nochev:true})+lrow({t:'Fallback outbox',s:'Not used · institutional email transport configured',nochev:true})+'</div>')},
 newThread(){openSheet('<h2 class="h2 mb8">Start a thread</h2><div class="field"><label class="label" for="nt-t">Title</label><input id="nt-t" placeholder="What do you want to discuss?"></div><div class="field"><label class="label" for="nt-k">Type</label><select id="nt-k"><option>Question</option><option>Discussion</option></select></div><button class="btn pri block" id="nt-go">Post thread</button>');$('#nt-go').onclick=()=>{const t=$('#nt-t').value.trim();if(!t)return toast('Add a title');S.threads.unshift({id:Date.now(),tags:[$('#nt-k').value],t,by:'Aisha Rahman',replies:[]});closeAll();render()}},
 openThread(v){S.f.th=+v;go('thread')},
 postReply(){const t=$('#treply').value.trim();if(!t)return toast('Write a reply first');S.threads.find(x=>x.id===S.f.th).replies.push(['Aisha Rahman',t]);render()},
 sub(){const x=S.threads.find(t=>t.id===S.f.th);x.subbed=!x.subbed;swapNext('[data-act="sub"]');toast(x.subbed?'Subscribed. You’ll get replies in Notifications.':'Unsubscribed');render()},
 compose(){openSheet('<h2 class="h2 mb8">Compose broadcast</h2><div class="label mb8">Send to</div><div class="chips" style="padding:0 0 12px" role="group" id="bc-aud">'+['All members (42)','Officers (4)','Going to Build Night (4)'].map((a,i)=>'<button class="chip" aria-pressed="'+(i===0)+'" data-aud="'+a+'">'+a+'</button>').join('')+'</div><div class="field"><label class="label" for="bc-s">Subject</label><input id="bc-s" value="Build Night: bring your laptop"></div><div class="field"><label class="label" for="bc-m">Message</label><textarea id="bc-m">See you Thursday at 6:30 PM in Room 402. Zoom link is in the Hub.</textarea></div><button class="btn pri block" id="bc-go">Send broadcast</button>');
  $$('#bc-aud [data-aud]').forEach(b=>b.onclick=()=>$$('#bc-aud [data-aud]').forEach(x=>x.setAttribute('aria-pressed',x===b)));$('#bc-go').onclick=()=>{const a=$('#bc-aud [aria-pressed="true"]').dataset.aud;S.sent.unshift({t:$('#bc-s').value||'Broadcast',a,when:'Just now'});audit('Aisha Rahman','Publishing','BROADCAST_SENT · '+a);closeAll();toast('Broadcast sent to '+a+' (simulated)');render()}},
 waOpen(){toast('In the real app this opens WhatsApp')},copyInvite(){try{navigator.clipboard.writeText('https://chat.whatsapp.com/sample-ai-club').then(()=>toast('Invite link copied (sample link)'),()=>toast('Invite link: chat.whatsapp.com/sample-ai-club'))}catch(e){toast('Invite link: chat.whatsapp.com/sample-ai-club')}},
 waShare(){openSheet('<h2 class="h2 mb8">Ready to share</h2><div class="msg wa">'+esc($('#waMsg').value)+'</div><p class="cap mt12 mb12">In the real app, WhatsApp opens with this message filled in. You press send there.</p><button class="btn pri block" id="wa-ok">Done</button>');$('#wa-ok').onclick=()=>{audit('Aisha Rahman','Publishing','WHATSAPP_SHARE_PREPARED');closeAll();toast('Share logged')}},
 newPost(){openSheet('<h2 class="h2 mb8">New blog story</h2><div class="field"><label class="label" for="bp-t">Title</label><input id="bp-t" placeholder="Story title"></div><button class="btn pri block" id="bp-go">Save as draft</button>');$('#bp-go').onclick=()=>{const t=$('#bp-t').value.trim();if(!t)return toast('Add a title');S.blog.push({t,st:'Draft',by:'Aisha Rahman'});closeAll();render()}},
 feat(v){S.blog[v].feat=!S.blog[v].feat;render()},publishBlog(v){S.blog[v].st='Published';S.blog[v].by='Published Nov 18';toast('Published to the club blog');render()},
 newTask(){openSheet('<h2 class="h2 mb8">Assign a task</h2><div class="field"><label class="label" for="tk-t">Task</label><input id="tk-t" placeholder="What needs doing?"></div><div class="two"><div class="field"><label class="label" for="tk-w">Assignee</label><select id="tk-w">'+S.members.map(m=>'<option>'+m.n+'</option>').join('')+'</select></div><div class="field"><label class="label" for="tk-d">Due</label><input id="tk-d" value="Nov 30"></div></div><button class="btn pri block" id="tk-go">Assign</button>');$('#tk-go').onclick=()=>{const t=$('#tk-t').value.trim();if(!t)return toast('Add a task');S.tasks.unshift({t,who:$('#tk-w').value,due:$('#tk-d').value,st:'To do'});closeAll();render()}},
 tick(v){const t=S.tasks[v];t.st=t.st==='Done'?'To do':'Done';swapNext('[data-act="tick"][data-v="'+v+'"]');render()},
 approve(v){const p=S.pending.splice(v,1)[0];S.members.push({n:p.n,r:'Member · Contributor',av:p.n.split(' ').map(x=>x[0]).join('')});audit('Aisha Rahman','Access','MEMBER_APPROVED · '+p.n);toast(p.n+' added to the directory');render()},
 decline(v){const p=S.pending.splice(v,1)[0];toast('Request from '+p.n+' declined');render()},
 member(v){const m=S.members.find(x=>x.n===v);openSheet('<div class="row mb12" style="justify-content:flex-start;gap:12px"><span class="avatar">'+m.av+'</span><div><b style="color:var(--indigo)">'+m.n+'</b><div class="cap">'+m.r+'</div></div></div><div class="stack"><button class="btn sec" data-act="soonA">Change role</button><button class="btn sec" data-act="soonA">Message</button></div>')},
 decide(v){const [id,d]=v.split('|');const r=S.reqs.find(x=>x.id===id);if(d==='approve'){r.step=3;r.st='Approved for setup'}else if(d==='info'){r.st='More information required'}else{r.st='Declined'}audit('Dr. Elena Vance','Governance','ACCOUNT_REQUEST_DECISION · '+id+' · '+r.st);toast(id+': '+r.st);render()},
 doc(v){toast(v+' opens as a file in the real app')},
 join(v){S.joined[v]=true;toast('Request sent to the club’s leads');render()},
 saveProfile(){toast('Club profile saved');audit('Aisha Rahman','Governance','CLUB_PROFILE_UPDATED')},
 sw(v,el){el.setAttribute('aria-checked',el.getAttribute('aria-checked')!=='true')},
 authorize(){audit('Dr. Elena Vance','Governance','LEADER_AUTHORIZED · '+$('#luser').value.split(' (')[0]);toast('Club leader authorized. Recorded in the audit log.')},
 revoke(v){const u=S.users[v];openSheet('<h2 class="h2 mb8">Revoke access for '+u.n+'?</h2><p class="cap mb16">They’ll be signed out everywhere and lose access to every club workspace.</p><div class="two"><button class="btn sec" id="rv-no">Cancel</button><button class="btn pri" id="rv-yes">Revoke</button></div>');$('#rv-no').onclick=closeAll;$('#rv-yes').onclick=()=>{u.a=false;audit('Dr. Elena Vance','Access','ACCESS_REVOKED · '+u.n);closeAll();render()}},
 pubJoin(){openSheet('<h2 class="h2 mb8">Request to join</h2><p class="cap mb12">Sign in with your CUNY email to send a join request to the club’s leads.</p><button class="btn pri block" id="pj">Sign in</button>');$('#pj').onclick=()=>{closeAll();go('signin')}},
 resetDemo(){location.hash='';location.reload()},
 shareEv(){closeAll();try{navigator.clipboard.writeText('https://missme2026.github.io/club-hub-demo/#public').then(()=>toast('Event link copied'),()=>toast('Event link: missme2026.github.io/club-hub-demo'))}catch(e){toast('Event link: missme2026.github.io/club-hub-demo')}},
 viewMembers(v){const c=S.clubs.find(x=>x.n===v);const list=c&&c.mine?S.members:[];openSheet('<h2 class="h2 mb8">'+v+'</h2><p class="cap mb12">'+(c?c.m:0)+' members · sample data</p>'+(list.length?'<div class="card">'+list.map(m=>lrow({av:m.av,t:m.n,s:m.r,nochev:true})).join('')+'</div>':'<div class="card pad" style="text-align:center"><p class="cap">'+(c&&c.m?'Member names for this club aren’t in the demo data.':'No members yet.')+'</p></div>'))},
 postEvent(){openSheet('<h2 class="h2 mb8">Post an event</h2><p class="cap mb12">Goes on the club calendar and Upcoming events. Sample only.</p><div class="field"><label class="label" for="pe-t">Event name</label><input id="pe-t" placeholder="e.g., AI Study Hall"></div><div class="two"><div class="field"><label class="label" for="pe-d">Date</label><input id="pe-d" type="date" value="2026-11-30"></div><div class="field"><label class="label" for="pe-h">Time</label><input id="pe-h" type="time" value="18:00"></div></div><div class="field"><label class="label" for="pe-k">Type</label><select id="pe-k"><option value="club">Club meeting</option><option value="workshop">Workshop</option><option value="campus">Campus event</option></select></div><div class="field"><label class="label" for="pe-w">Where</label><input id="pe-w" value="Zoom"></div><button class="btn pri block" id="pe-go">Post event</button>');
  $('#pe-go').onclick=()=>{const t=$('#pe-t').value.trim();if(!t)return toast('Add an event name');const d=new Date($('#pe-d').value+'T'+$('#pe-h').value);if(isNaN(d))return toast('Pick a date and time');const k=$('#pe-k').value;const tag={club:'Club meeting',workshop:'Workshop',campus:'Campus event'}[k];
   const when=d.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'})+' · '+d.toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'});
   EVENTS.push({id:'e'+Date.now(),type:k,mon:d.toLocaleDateString('en-US',{month:'short'}).toUpperCase(),day:String(d.getDate()),when:d.toLocaleDateString('en-US',{weekday:'short'})+' '+d.toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'}),title:t,meta:when+' · '+($('#pe-w').value||'TBA'),going:0,seats:30,img:'',tag});
   if(d.getMonth()===10&&d.getFullYear()===2026)S.cal.push({d:d.getDate(),k:'event',t,s:d.toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})+' · '+($('#pe-w').value||'TBA')});
   audit('Aisha Rahman','Publishing','EVENT_POSTED · '+t);closeAll();toast('Event posted');S.filter='all';$$('#ev-filter .chip').forEach(x=>x.setAttribute('aria-pressed',x.dataset.f==='all'));renderEvents();$('#ev-count').textContent=EVENTS.length+' events this month'}},
 soonA(){toast('Not part of this demo yet')}};
document.addEventListener('click',e=>{const a=e.target.closest('[data-act]');if(a&&ACT[a.dataset.act]){e.preventDefault();ACT[a.dataset.act](a.dataset.v,a);return}
 const c=e.target.closest('[data-chip]');if(c){S.f[c.dataset.chip]=c.dataset.v;render();return}
 const d=e.target.closest('[data-day]');if(d){S.f[d.dataset.day]=+d.dataset.v;render()}});
